const D = { energy:.7, density:.5, speed:1, hue:220, x:.5, y:.55, branch:.6, rate:.5, style:'storm', seed:0, act:'scattered' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const storm=st==='storm',tesla=st==='tesla',engr=st==='engraving',blue=st==='blueprint';
const en=P.energy*(0.55+0.5*K.intensity);
const act=P.act;

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.cl=[]; for(let i=0;i<9;i++) S.cl.push({x:fr(i*2+1),y:fr(i*2+2)*0.42,r:0.28+fr(i*2+3)*0.5,ph:fr(i*2+4)*6.28,sp:0.25+fr(i*2+5)*0.8}); S.strikeT=-999; S.bolt=null; S.idx=null; S.sc=0; }

// ---- strike scheduler ----
const period=Math.max(0.7, lrp(4.5,1.1,clp(P.rate,0,1)) * (act==='scattered'?1.7 : act==='supercell'? lrp(1.6,0.5,K.intensity) : 1) / Math.max(0.3,P.speed));
const idx=Math.floor(K.bar/period);
let doStrike=false;
if(S.idx==null) S.idx=idx;
if(idx!==S.idx){ S.idx=idx; doStrike=true; }
if(A.bass>0.62 && (K.t-(S.strikeT||-9))>0.5) doStrike=true;
if(doStrike){
  S.strikeT=K.t; S.sc=(S.sc||0)+1;
  const rr=k=>{const s=Math.sin(k*127.1+(P.seed+S.sc*57.31)*311.7)*43758.5453;return s-Math.floor(s);};
  // build jagged bolt as normalized polyline + branches
  const ox=clp(P.x + (rr(1)-0.5)*0.18, 0.08,0.92);
  const gy=clp(P.y+0.32,0.4,0.98);
  const segs=[]; let x=ox,y=0.02,k=0;
  const steps=10+Math.floor(rr(2)*5);
  const pts=[{x,y}];
  for(let s2=0;s2<steps;s2++){ y+=(gy-0.02)/steps; x+=(rr(k++)-0.5)*0.09; x=clp(x,0.04,0.96); pts.push({x,y}); }
  for(let i2=0;i2<pts.length-1;i2++) segs.push({a:pts[i2],b:pts[i2+1],g:0,w:1});
  // branches
  const nb=Math.round(lrp(1,7,clp(P.branch,0,1)));
  for(let bI=0;bI<nb;bI++){ const anchor=pts[2+Math.floor(rr(30+bI)*(pts.length-4))]; if(!anchor)continue; let bx=anchor.x,by=anchor.y; const bl=2+Math.floor(rr(40+bI)*3); const dir=(rr(50+bI)-0.5); for(let s3=0;s3<bl;s3++){ const nx=clp(bx+dir*0.05+(rr(60+bI*7+s3)-0.5)*0.06,0.02,0.98); const ny=by+(gy-by)*0.16; segs.push({a:{x:bx,y:by},b:{x:nx,y:ny},g:1,w:0.55}); bx=nx;by=ny; } }
  S.bolt={segs,ox,gy};
}

// ---- storm cloud baseline (continuous roil, always animating) ----
blendMode(BLEND); noStroke();
for(let i=0;i<S.cl.length;i++){ const c=S.cl[i];
  const dx=frc(c.x + K.t*0.012*c.sp*P.speed)*1.2-0.1;
  const cxp=dx*W; const cyp=(c.y)*Hh*0.9;
  const rr2=u*c.r*(0.9+0.12*Math.sin(K.t*0.4*c.sp+c.ph));
  const bri=8+6*(0.5+0.5*Math.sin(K.t*0.5+c.ph))+en*4;
  for(let r=4;r>0;r--){ const t=r/4; fill(md(H+6,360), lrp(30,55,t), bri*(1-t*0.5), 26*(1-t)); ellipse(cxp,cyp,rr2*t*2.2,rr2*t*1.1); }
}
// faint continuous heat-flicker glow (partial, upper region)
const hf=(0.5+0.5*Math.sin(K.t*1.7)+0.4*Math.sin(K.t*3.3+1))*0.5;
blendMode(ADD); noStroke();
fill(md(H-6,360),20,90, (4+en*5)*hf); ellipse(W*0.5, Hh*0.18, W*1.1, Hh*0.6);
blendMode(BLEND);

// ---- rain (continuous fall -> guaranteed motion floor) ----
if(!blue){
  const nr=Math.round(lrp(20,130,clp(P.density,0,1)));
  stroke(md(H+2,360),18,88, storm?38:tesla?42:60); strokeWeight(Math.max(0.7,u*0.0014));
  const wind=(P.x-0.5)*u*0.12;
  for(let i=0;i<nr;i++){ const rx=fr(i*4+1), rsp=0.6+fr(i*4+2)*0.9, rl=0.03+fr(i*4+3)*0.05;
    const ry=frc(fr(i*4+4)+K.t*rsp*0.35*P.speed);
    const sx=rx*W+wind*ry, sy=ry*Hh; line(sx,sy, sx+wind*0.12+u*0.008, sy+u*rl); }
  noStroke();
}

// ---- bolt + partial afterglow ----
if(S.bolt){
  const age=K.t-S.strikeT;
  const life=clp(1-age/0.55,0,1); // ~0.55s visible
  if(life>0){
    const flick=life*(0.55+0.45*Math.sin(K.t*55));
    // partial afterglow: additive glow around bolt origin, upper region only (strobe-safe)
    blendMode(ADD); noStroke();
    const glow=flick*(0.5+en);
    const ogx=S.bolt.ox*W, ogy=Hh*0.25;
    for(let r=3;r>0;r--){ const t=r/3; fill(md(blue?190:H-4,360),18,95, 22*glow*(1-t)); ellipse(ogx,ogy, u*1.0*t, Hh*0.7*t); }
    // the bolt path
    for(let pass=0;pass<(engr?1:2);pass++){
      const core=pass===1;
      for(let i=0;i<S.bolt.segs.length;i++){ const sg=S.bolt.segs[i];
        const ax=sg.a.x*W, ay=sg.a.y*Hh, bx=sg.b.x*W, by=sg.b.y*Hh;
        if(engr){
          // scraperboard: crisp pale strokes, hatched, light-on-dark
          stroke(md(H,360),6,96, 92*life*(sg.g?0.6:1)); strokeWeight(Math.max(1,u*0.0026*sg.w*(sg.g?0.6:1))); line(ax,ay,bx,by);
          if(!sg.g && i%2===0){ stroke(md(H,360),4,70,40*life); strokeWeight(Math.max(0.5,u*0.0009)); const mx=(ax+bx)/2,my=(ay+by)/2; line(mx-u*0.01,my,mx+u*0.01,my); }
        } else if(blue){
          stroke(md(190,360),70,100, 85*life*(sg.g?0.6:1)); strokeWeight(Math.max(0.8,u*0.0016*(sg.g?0.6:1))); line(ax,ay,bx,by);
        } else {
          const hh=tesla? md(H+70,360):md(H-4,360);
          stroke(hh, core?15:70, 100, (core?95:60)*flick*(sg.g?0.55:1));
          strokeWeight(Math.max(1,u*(core?0.0018:0.006)*sg.w));
          line(ax,ay,bx,by);
        }
      }
    }
    // blueprint measurement ticks along bolt
    if(blue){ stroke(md(190,360),45,90,50*life); strokeWeight(Math.max(0.5,u*0.001));
      for(let i=0;i<S.bolt.segs.length;i+=2){ const sg=S.bolt.segs[i]; const mx=(sg.a.x+sg.b.x)/2*W,my=(sg.a.y+sg.b.y)/2*Hh; line(mx-u*0.012,my,mx+u*0.012,my); } }
    noStroke(); blendMode(BLEND);
  }
}
blendMode(BLEND);
